      var notes=(fermes.length ? "<br>Fermé ce jour-là, sans effet sur l'ordre : "+esc(fermes.join(", "))+"." : "")+
        (ignores.length ? "<br>Horaires qui dépendent de la date, ignorés faute de date : "+esc(ignores.join(", "))+"." : "");
      var fin=function(r){ return hhmm(r.fin); };
