    var hors=(FLUX.flux||[]).filter(function(f){ return date<f.du || date>f.au; });
    if(!FLUX.flux) hors=(date<FLUX.du || date>FLUX.au) ? [{nom:"transports en commun",du:FLUX.du,au:FLUX.au}] : [];
    if(!hors.length) return null;
    var g={}, ordre=[]; hors.forEach(function(f){ var k=f.du+"|"+f.au; if(!g[k]){ g[k]={noms:[],du:f.du,au:f.au}; ordre.push(k); } g[k].noms.push(f.nom); });
