  /* ---------- vols : lecture des réponses des connecteurs eDreams et Expedia, contraintes, tri ----------
     Fonctions pures, sans accès à la page : testées par outils/test_vols.js sur de vraies réponses des deux connecteurs.
     Les deux sources ne donnent pas la même devise (eDreams : euros ; Expedia : dollars américains) et aucun taux de change
     n'est disponible ici : les prix ne sont jamais convertis, ils sont comparés dans la devise de chaque offre. */
  function volDureeMin(t){            // « 9h 48m », « 2h », « 45m »
    var h=/(\d+)\s*h/.exec(t||""), m=/(\d+)\s*m/.exec(t||"");
    return (h?parseInt(h[1],10)*60:0)+(m?parseInt(m[1],10):0);
  }
