    var t=transferts||{};
    v.porteAPorte=(t.dep&&t.dep[v.aeroportDep]!=null?t.dep[v.aeroportDep]:45)+(c.margeDepart||0)+v.duree+(c.margeArrivee||0)+(t.arr&&t.arr[v.aeroportArr]!=null?t.arr[v.aeroportArr]:45);
