  /* « temps contre prix » : valeur d'une heure, dans la devise de l'offre (5 économiser, 15 équilibré, 40 gagner du temps) */
  function volCout(v,valeurHeure){ return v.prixPersonne+valeurHeure*(v.porteAPorte/60); }
