  function volsHeure(m){ return hhmm(m%1440)+(m>=1440?" (+"+Math.floor(m/1440)+" j)":""); }
  // marges de sécurité estimées selon le pays de départ : présentation à l'aéroport et sortie de l'aéroport d'arrivée
  var VOLS_MARGES={US:{avant:120,apres:60},CA:{avant:180,apres:30}};
