    ctx.font=Math.round(11*k)+"px Arial, sans-serif"; ctx.textAlign="right"; ctx.textBaseline="alphabetic";
    var aw=ctx.measureText(att).width;
    ctx.fillStyle="rgba(255,255,255,0.85)"; ctx.fillRect(W-aw-14*k,H-20*k,aw+14*k,20*k);
    ctx.fillStyle="#33302a"; ctx.fillText(att,W-6*k,H-6*k);
