  function joursEnregistres(id){ var s=lireVilleStock(id); return s ? s.jours : []; }
  // les villes qui ont des étapes, dans l'ordre du voyage : par première date, et à date égale celle d'où part un vol d'abord
  function groupesVoyage(){
    var gs=[];
    VILLES.forEach(function(v){
      var js=v.id===VILLE.id ? JOURS.map(function(d){ return {etapes:d.etapes,modes:d.modes,date:d.date||""}; }) : joursEnregistres(v.id);
      if(!js.some(function(d){ return d.etapes.length; })) return;
      var jours=js.map(function(d,k){ return {ville:v,k:k,etapes:d.etapes,modes:d.modes,date:d.date,legs:[],horaires:[]}; });
      var dates=jours.filter(function(d){ return d.date && d.etapes.length; }).map(function(d){ return d.date; }).sort();
      var part=jours.some(function(d){ return d.etapes.some(function(p){ return p.vol && p.vol.sens==="depart"; }); });
      gs.push({ville:v,jours:jours,premiere:dates[0]||"9999",part:part?0:1});
    });
    gs.sort(function(a,b){ return a.premiere<b.premiere?-1:a.premiere>b.premiere?1:a.part-b.part; });
    return gs;
  }
  // pendant l'échange des données de ville, rien d'autre ne doit toucher aux étapes, aux trajets ni à la carte
  function bloquerInterface(b){
    var rail=document.querySelector(".rail"), sc=document.getElementById("scene");
    Array.prototype.forEach.call(rail.children,function(c){ if(c.id!=="rapportetat" && c.id!=="annonce") c.inert=b; });
    if(sc) sc.inert=b;
  }
  // exécute un travail qui peut échanger les données de ville, puis remet toujours celles de la ville affichée
