  async function livrer(blob,nom){
    var dl=null; try{ dl=(window.claude && window.claude.use) ? await window.claude.use("downloads") : null; }catch(e){ dl=null; }
    if(dl){
      try{ await dl.save({filename:nom,data:blob}); return "enregistre"; }
      catch(e){ if(e && e.code==="declined") return "refuse"; throw new Error((e && e.message) || "enregistrement impossible"); }
    }
    var a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download=nom; document.body.appendChild(a); a.click(); a.remove();
    return "lien";
  }
