  /* ---------- changement de ville sans recharger la page ----------
     Le choix ne passe plus par le stockage du navigateur ni par un rechargement : les données de la ville quittée sont mises en
     réserve, celles de la ville choisie sont chargées (une seule fois, puis gardées), et la carte est replacée. L'itinéraire de
     chaque ville reste en mémoire pendant la visite, même quand le navigateur refuse d'enregistrer. */
  var CTX_VILLES={}, villeEnCours=false;
  function copieJson(x){ return JSON.parse(JSON.stringify(x)); }
  async function changerVille(id){
    var sel=document.getElementById("ville"), cible=null;
    VILLES.forEach(function(v){ if(v.id===id) cible=v; });
    if(!cible || cible.id===VILLE.id){ if(sel) sel.value=VILLE.id; return; }
    if(villeEnCours || optimEnCours || rapportEnCours || !GR){
      if(sel) sel.value=VILLE.id;
      annonce(GR ? "Une opération est en cours : patientez avant de changer de ville." : "Les données de la ville affichée se chargent encore.");
      return;
    }
    try{ if(document.activeElement && document.activeElement!==document.body && document.activeElement.blur) document.activeElement.blur(); }catch(x){}   // valide un champ en cours de saisie avant de quitter la ville
    villeEnCours=true; if(sel) sel.disabled=true;
    var avant=VILLE, ctxAvant=null, ctxCible=null;
    bloquerInterface(true); etat.hidden=false; etat.textContent="Chargement de "+cible.nom+"…";
    version++;                       // les calculs de trajets en cours pour la ville quittée sont abandonnés
    try{
      if(cible.od && !cible.od.pret) await odPreparer(cible);
      sauver();
      await attendreCharges(); await pause();
      ctxAvant=capturerCtx(); CTX_VILLES[avant.id]=ctxAvant;
      // la mémoire d'une ville visitée est libérée dès qu'on en visite une autre : seules la ville quittée et la ville demandée restent en cache
      Object.keys(CTX_VILLES).forEach(function(k){ if(k!==avant.id && k!==cible.id) delete CTX_VILLES[k]; });
      ctxEmprunte=true;
      ctxCible=CTX_VILLES[cible.id];
      if(ctxCible) appliquerCtx(ctxCible);
      else { ctxCible=await chargerCtxVille(cible,true); CTX_VILLES[cible.id]=ctxCible; }
    }catch(err){
      appliquerCtx(ctxAvant || capturerCtx()); ctxEmprunte=false; bloquerInterface(false); villeEnCours=false;
      if(sel){ sel.disabled=false; sel.value=VILLE.id; }
      etat.hidden=false; etat.textContent="Les données de "+cible.nom+" n'ont pas pu être chargées : "+err.message+". "+VILLE.nom+" reste affichée.";
      setTimeout(function(){ if(!villeEnCours) etat.hidden=true; },6000);
      return;
    }
    // à partir d'ici les variables sont celles de la ville choisie
    CLE="itineraire-"+cible.id+"-v1"; INIT=copieJson(cible.depart);
    JOURS=[]; MODES={}; jourActif=0;
    var e=lireSauvegarde();
    if(!e){ e=copieJson(INIT); JOURS=[{etapes:e,modes:MODES,date:""}]; jourActif=0; }
    etapes=e; courant=etapes.length ? etapes[0].uid : null; legs=[]; editH=null;
    base=[]; baseProm=null; autour=null; onglet="tous"; champQ.value="";
    zoneEffacer(); barreAutour.hidden=true; onglets.hidden=false; ajout.hidden=true; ouvrir.setAttribute("aria-expanded","false"); finPose(); formpose.hidden=true; retirerApercu();
    optim.hidden=true; ordreAvant=null; hbPanneau.hidden=true; hbBtn.setAttribute("aria-expanded","false"); hbRes=[]; hbListe.innerHTML=""; budItems=[]; budSortie.innerHTML="";
    carte.setMaxBounds(null); carte.setMinZoom(cible.zoom_min); carte.jumpTo({center:cible.centre,zoom:cible.zoom}); carte.setMaxBounds(cible.limites);
    carte.getSource("eau").setData(D("eau.json")); carte.getSource("vert").setData(D("vert.json"));
    FC.voies=VIDE; FC.bati=VIDE; carte.getSource("voies").setData(VIDE); carte.getSource("bati").setData(VIDE); carte.getSource("axes").setData(FC.axes);
    ctxEmprunte=false;
    if(PERSISTANCE){ try{ localStorage.setItem("ville-active",cible.id); }catch(x){} }
    bloquerInterface(false); villeEnCours=false;
    if(sel){ sel.disabled=false; sel.value=cible.id; }
    etat.hidden=true; rendreJours(); recalculer(); ensemble(); majSources(); programmer();
    if(VILLES_VOL.length>=2) volsRemplir();
    CTX_VILLES={};      // les données de la ville quittée sont libérées : elles se rechargent au retour, mais la mémoire reste celle d'une seule ville
    if(cible.od){ window.__odTouch(cible); setTimeout(odAuto,300); }
    annonce("Ville affichée : "+cible.nom);
  }

  /* ---------- enregistrer et rouvrir un voyage : fichier .json ou code de partage ---------- */
  var VP_FORMAT="itineraire-voyage", VP_MAX=6*1024*1024;
  var vpBtn=document.getElementById("vpbtn"), vpPanneau=document.getElementById("voyagepanel"), vpCode=document.getElementById("vpcode"),
      vpEtat=document.getElementById("vpetat"), vpInput=document.getElementById("vpinput");
  function vpMsg(t,erreur){ vpEtat.hidden=!t; vpEtat.textContent=t||""; vpEtat.style.color=erreur ? "var(--rouge,#9a2f22)" : ""; if(t) annonce(t); }
  function vpObjet(){
    sauver();
    var villes={};
    VILLES.forEach(function(v){
      var st=lireVilleStock(v.id);
      if(st && st.jours.some(function(d){ return d.etapes.length; })) villes[v.id]={jours:st.jours,actif:st.actif};
    });
    var vd=document.getElementById("villedepart");
    return {format:VP_FORMAT,version:1,cree:new Date().toISOString(),ville_active:VILLE.id,villes:villes,od:VILLES.filter(function(v){ return v.od && villes[v.id]; }).map(function(v){ return [v.nom,v.pays,v.lon,v.lat]; }),
            vols:volsRet,budget:budLire(),depart:vd ? vd.value : ""};
  }
  // contrôle d'un voyage venu d'un fichier ou d'un code : seules les données reconnues et valides sont gardées
  function vpValider(o){
    if(!o || o.format!==VP_FORMAT || !o.villes || typeof o.villes!=="object") throw new Error("ce n'est pas un voyage enregistré par cette application");
    var villes={}, n=0;
    if(Array.isArray(o.od)) o.od.slice(0,20).forEach(function(e){ if(Array.isArray(e) && e.length>=4) odCreerVille(e); });
    VILLES.forEach(function(v){
      var st=o.villes[v.id];
      if(st && sauvegardeValide(st)){ villes[v.id]={jours:st.jours,actif:Math.max(0,Math.min(st.jours.length-1,parseInt(st.actif,10)||0))}; n++; }
    });
    if(!n) throw new Error("le voyage ne contient aucune journée lisible");
    var vols=Array.isArray(o.vols) ? o.vols.filter(function(x){ return x && typeof x==="object" && typeof x.cle==="string"; }).slice(0,60) : [];
    var b=o.budget && typeof o.budget==="object" ? o.budget : {}, taux={};
    if(b.taux && typeof b.taux==="object") Object.keys(b.taux).slice(0,20).forEach(function(k){ var x=Number(b.taux[k]); if(isFinite(x) && x>0 && x<1e6) taux[String(k).slice(0,8)]=x; });
    var bud={voyageurs:Math.max(0,Math.min(20,parseInt(b.voyageurs,10)||0)),ref:typeof b.ref==="string" ? b.ref.slice(0,8) : "",taux:taux};
    var act=(typeof o.ville_active==="string" && villes[o.ville_active]) ? o.ville_active : Object.keys(villes)[0];
    return {villes:villes,vols:vols,budget:bud,active:act,depart:typeof o.depart==="string" ? o.depart.slice(0,60) : ""};
  }
  async function vpAppliquer(v){
    if(villeEnCours || optimEnCours || rapportEnCours || !GR) throw new Error("une opération est en cours ou les données de la ville se chargent encore : réessayez dans un instant");
    version++;
    VILLES.forEach(function(x){
      if(v.villes[x.id]) ecrireVilleStock(x.id,v.villes[x.id]);
      else if(x.id!==VILLE.id) effacerVilleStock(x.id);
    });
    var st=v.villes[VILLE.id] ? lireVilleStock(VILLE.id) : null;
    if(st){ JOURS=st.jours; jourActif=st.actif; MODES=JOURS[jourActif].modes; etapes=JOURS[jourActif].etapes; }
    else { etapes=copieJson(INIT); MODES={}; JOURS=[{etapes:etapes,modes:MODES,date:""}]; jourActif=0; ecrireVilleStock(VILLE.id,{jours:JOURS,actif:0}); }
    volsRet=v.vols; volsSauver(); budParams=v.budget; budEcrire();
    var vd=document.getElementById("villedepart"); if(vd) vd.value=v.depart;
    courant=etapes.length ? etapes[0].uid : null; legs=[]; editH=null; zoneEffacer(); finPose(); optim.hidden=true; ordreAvant=null; budItems=[]; budSortie.innerHTML="";
    rendreJours(); recalculer(); ensemble(); majSources(); programmer(); volsRetenusHTML(); if(volsRes) volsAfficher();
    if(v.active!==VILLE.id){ await changerVille(v.active); }
  }
  async function vpEncoder(obj){
    var oct=new TextEncoder().encode(JSON.stringify(obj)), pre="J1.";
    if(window.CompressionStream){
      try{ oct=new Uint8Array(await new Response(new Blob([oct]).stream().pipeThrough(new CompressionStream("gzip"))).arrayBuffer()); pre="G1."; }catch(e){ oct=new TextEncoder().encode(JSON.stringify(obj)); pre="J1."; }
    }
    var bin="", pas=0x8000; for(var i=0;i<oct.length;i+=pas) bin+=String.fromCharCode.apply(null,oct.subarray(i,i+pas));
    return pre+btoa(bin).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");
  }
  async function vpDecoder(code){
    var c=String(code||"").replace(/\s+/g,"");
    var pre=c.slice(0,3); if(pre!=="G1." && pre!=="J1.") throw new Error("ce code n'est pas un code de voyage");
    if(c.length>VP_MAX) throw new Error("code trop long");
    var b=c.slice(3).replace(/-/g,"+").replace(/_/g,"/"); while(b.length%4) b+="=";
    var bin=atob(b), oct=new Uint8Array(bin.length); for(var i=0;i<bin.length;i++) oct[i]=bin.charCodeAt(i);
    if(pre==="G1."){
      if(!window.DecompressionStream) throw new Error("ce navigateur ne sait pas lire ce code compressé");
      oct=new Uint8Array(await new Response(new Blob([oct]).stream().pipeThrough(new DecompressionStream("gzip"))).arrayBuffer());
    }
    return JSON.parse(new TextDecoder().decode(oct));
  }
  function vpResume(v){
    var j=0,e=0; Object.keys(v.villes).forEach(function(id){ v.villes[id].jours.forEach(function(d){ if(d.etapes.length){ j++; e+=d.etapes.length; } }); });
    return Object.keys(v.villes).length+" ville"+(Object.keys(v.villes).length>1?"s":"")+", "+j+" journée"+(j>1?"s":"")+", "+e+" étape"+(e>1?"s":"");
  }
